import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { PointerLockControls } from 'three/examples/jsm/controls/PointerLockControls';
import { GameState } from '../../../types/gameState';

interface SecretChamber3DProps {
  onInteract?: (objectId: string, objectType: string) => void;
  onUpdateGameState?: (state: GameState) => void;
}

export const SecretChamber3D: React.FC<SecretChamber3DProps> = ({ onInteract, onUpdateGameState }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const controlsRef = useRef<PointerLockControls | null>(null);
  const moveStateRef = useRef({
    forward: false,
    backward: false,
    left: false,
    right: false,
  });
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const gameStateRef = useRef<GameState>({
    // Score et temps
    score: 1000,
    elapsedTime: 0,
    
    // États de la bibliothèque
    hasFoundAncientBook: false,
    hasDecodedSymbols: false,
    hasAncientKey: false,
    
    // États du laboratoire
    hasExaminedMicroscope: false,
    hasCompletedChemicalMix: false,
    hasCrystalKey: false,
    
    // États de la chambre secrète
    hasPlacedArtifact: false,
    hasCompletedRitual: false,
    
    // État général
    currentHint: undefined,
    gameCompleted: false,
    currentRoom: 'secret-chamber',
    inventory: []
  });

  useEffect(() => {
    if (!mountRef.current) return;

    // Configuration de base
    const scene = new THREE.Scene();
    sceneRef.current = scene;
    scene.background = new THREE.Color(0x000000); // Salle complètement sombre
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    cameraRef.current = camera;
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    mountRef.current.appendChild(renderer.domElement);

    // Garder une référence au mountRef.current pour le nettoyage
    const mountElement = mountRef.current;

    // Fonction pour rendre un objet interactif
    const makeInteractive = (object: THREE.Object3D, id: string, type: string) => {
      object.userData.interactive = true;
      object.userData.id = id;
      object.userData.type = type;
    };

    // Sol circulaire
    const floorGeometry = new THREE.CircleGeometry(10, 32);
    const floorMaterial = new THREE.MeshStandardMaterial({
      color: 0x1a1a1a,
      roughness: 0.8,
      metalness: 0.2
    });
    const floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    scene.add(floor);

    // Mur circulaire
    const wallGeometry = new THREE.CylinderGeometry(10, 10, 4, 32, 1, true);
    const wallMaterial = new THREE.MeshStandardMaterial({
      color: 0x2a2a2a,
      roughness: 0.7,
      metalness: 0.3,
      side: THREE.BackSide
    });
    const wall = new THREE.Mesh(wallGeometry, wallMaterial);
    wall.position.y = 2;
    wall.receiveShadow = true;
    scene.add(wall);

    // Hiéroglyphes sur les murs
    const createHieroglyphs = () => {
      const segments = 16;
      const angleStep = (Math.PI * 2) / segments;
      
      for (let i = 0; i < segments; i++) {
        const angle = i * angleStep;
        const x = Math.cos(angle) * 9.9;
        const z = Math.sin(angle) * 9.9;

        const glyphGeometry = new THREE.PlaneGeometry(1.2, 0.8);
        const glyphMaterial = new THREE.MeshStandardMaterial({
          color: 0x3D2B1F,
          roughness: 1,
          metalness: 0,
          emissive: 0x000000
        });
        const glyph = new THREE.Mesh(glyphGeometry, glyphMaterial);
        glyph.position.set(x, 2, z);
        glyph.lookAt(0, 2, 0);
        scene.add(glyph);
      }
    };

    // Vitrine avec l'artéfact
    const createArtifactCase = () => {
      const caseGroup = new THREE.Group();

      // Base
      const baseGeometry = new THREE.CylinderGeometry(0.8, 1, 0.2, 8);
      const baseMaterial = new THREE.MeshStandardMaterial({
        color: 0xB87333,
        roughness: 0.3,
        metalness: 0.8
      });
      const base = new THREE.Mesh(baseGeometry, baseMaterial);
      caseGroup.add(base);

      // Vitrine en verre
      const glassGeometry = new THREE.CylinderGeometry(0.7, 0.7, 1.5, 16, 1, true);
      const glassMaterial = new THREE.MeshPhysicalMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.2,
        roughness: 0,
        metalness: 0.2,
        clearcoat: 1
      });
      const glass = new THREE.Mesh(glassGeometry, glassMaterial);
      glass.position.y = 0.85;
      caseGroup.add(glass);

      // Artéfact (une sorte d'amulette)
      const artifactGroup = new THREE.Group();
      
      // Corps de l'amulette
      const amuletGeometry = new THREE.TorusGeometry(0.2, 0.05, 16, 100);
      const amuletMaterial = new THREE.MeshStandardMaterial({
        color: 0xFFD700,
        roughness: 0.3,
        metalness: 0.8
      });
      const amulet = new THREE.Mesh(amuletGeometry, amuletMaterial);
      artifactGroup.add(amulet);

      // Symboles sur l'amulette
      const symbolsGeometry = new THREE.TorusGeometry(0.15, 0.02, 16, 8);
      const symbols = new THREE.Mesh(symbolsGeometry, amuletMaterial);
      symbols.rotation.x = Math.PI / 4;
      artifactGroup.add(symbols);

      artifactGroup.position.y = 0.85;
      makeInteractive(artifactGroup, 'sacred-artifact', 'artifact');
      caseGroup.add(artifactGroup);

      caseGroup.position.set(5, 0, 0);
      scene.add(caseGroup);
    };

    // Piédestal pour l'artéfact
    const createPedestal = () => {
      const pedestalGroup = new THREE.Group();

      // Base du piédestal
      const baseGeometry = new THREE.CylinderGeometry(1, 1.2, 0.3, 8);
      const pedestalMaterial = new THREE.MeshStandardMaterial({
        color: 0x2a2a2a,
        roughness: 0.7,
        metalness: 0.3
      });
      const base = new THREE.Mesh(baseGeometry, pedestalMaterial);
      pedestalGroup.add(base);

      // Colonne
      const columnGeometry = new THREE.CylinderGeometry(0.6, 0.8, 1.5, 8);
      const column = new THREE.Mesh(columnGeometry, pedestalMaterial);
      column.position.y = 0.9;
      pedestalGroup.add(column);

      // Plateau supérieur
      const topGeometry = new THREE.CylinderGeometry(0.8, 0.6, 0.2, 8);
      const top = new THREE.Mesh(topGeometry, pedestalMaterial);
      top.position.y = 1.75;
      pedestalGroup.add(top);

      // Symboles gravés
      const symbolsGeometry = new THREE.RingGeometry(0.3, 0.4, 16);
      const symbolsMaterial = new THREE.MeshStandardMaterial({
        color: 0x3D2B1F,
        roughness: 1,
        metalness: 0
      });
      const symbols = new THREE.Mesh(symbolsGeometry, symbolsMaterial);
      symbols.rotation.x = -Math.PI / 2;
      symbols.position.y = 1.86;
      pedestalGroup.add(symbols);

      pedestalGroup.position.set(-5, 0, 0);
      makeInteractive(pedestalGroup, 'artifact-pedestal', 'pedestal');
      scene.add(pedestalGroup);
    };

    // Créer les éléments de la salle
    createHieroglyphs();
    createArtifactCase();
    createPedestal();

    // Éclairage mystique
    const ambientLight = new THREE.AmbientLight(0x1a1a1a, 0.3);
    scene.add(ambientLight);

    // Lumières focalisées
    const createFocusLight = (position: THREE.Vector3, target: THREE.Vector3, color: number = 0x3366ff) => {
      const light = new THREE.SpotLight(color, 1);
      light.position.copy(position);
      light.target.position.copy(target);
      light.angle = Math.PI / 6;
      light.penumbra = 0.5;
      light.decay = 2;
      light.distance = 15;
      light.castShadow = true;
      scene.add(light);
      scene.add(light.target);
      return light;
    };

    createFocusLight(
      new THREE.Vector3(5, 4, 0),
      new THREE.Vector3(5, 0, 0),
      0x6600cc
    );
    createFocusLight(
      new THREE.Vector3(-5, 4, 0),
      new THREE.Vector3(-5, 0, 0),
      0x3366ff
    );

    // Contrôles et animation
    camera.position.set(0, 1.7, 5);
    const controls = new PointerLockControls(camera, document.body);
    controlsRef.current = controls;

    // Gestion des interactions
    const handleKeyDown = (event: KeyboardEvent) => {
      switch (event.code) {
        case 'KeyW':
        case 'ArrowUp':
          moveStateRef.current.forward = true;
          break;
        case 'KeyS':
        case 'ArrowDown':
          moveStateRef.current.backward = true;
          break;
        case 'KeyA':
        case 'ArrowLeft':
          moveStateRef.current.left = true;
          break;
        case 'KeyD':
        case 'ArrowRight':
          moveStateRef.current.right = true;
          break;
        case 'KeyE':
          handleInteraction();
          break;
      }
    };

    const handleKeyUp = (event: KeyboardEvent) => {
      switch (event.code) {
        case 'KeyW':
        case 'ArrowUp':
          moveStateRef.current.forward = false;
          break;
        case 'KeyS':
        case 'ArrowDown':
          moveStateRef.current.backward = false;
          break;
        case 'KeyA':
        case 'ArrowLeft':
          moveStateRef.current.left = false;
          break;
        case 'KeyD':
        case 'ArrowRight':
          moveStateRef.current.right = false;
          break;
      }
    };

    const handleClick = () => {
      if (controlsRef.current) {
        controlsRef.current.lock();
      }
      handleInteraction();
    };

    const handleInteraction = () => {
      if (!cameraRef.current || !sceneRef.current) return;

      const raycaster = new THREE.Raycaster();
      const center = new THREE.Vector2(0, 0);

      raycaster.setFromCamera(center, cameraRef.current);
      const intersects = raycaster.intersectObjects(sceneRef.current.children, true);

      for (const intersect of intersects) {
        let object: THREE.Object3D | null = intersect.object;

        // Remonter dans la hiérarchie des objets pour trouver celui qui est interactif
        while (object && !object.userData.interactive) {
          object = object.parent;
        }

        if (object && object.userData.interactive) {
          onInteract?.(object.userData.id, object.userData.type);
          break;
        }
      }
    };

    // Mouvement du joueur
    const moveSpeed = 0.15;
    const updatePlayerPosition = () => {
      if (!controlsRef.current || !controlsRef.current.isLocked) return;

      const camera = controlsRef.current.getObject();
      const moveState = moveStateRef.current;

      const newPosition = camera.position.clone();
      const direction = new THREE.Vector3();

      if (moveState.forward) {
        const testPosition = newPosition.clone();
        direction.set(0, 0, -1);
        direction.applyQuaternion(camera.quaternion);
        direction.y = 0;
        direction.normalize();
        testPosition.add(direction.multiplyScalar(moveSpeed));
        if (isPositionValid(testPosition)) {
          camera.translateZ(-moveSpeed);
        }
      }
      if (moveState.backward) {
        const testPosition = newPosition.clone();
        direction.set(0, 0, 1);
        direction.applyQuaternion(camera.quaternion);
        direction.y = 0;
        direction.normalize();
        testPosition.add(direction.multiplyScalar(moveSpeed));
        if (isPositionValid(testPosition)) {
          camera.translateZ(moveSpeed);
        }
      }
      if (moveState.left) {
        const testPosition = newPosition.clone();
        direction.set(-1, 0, 0);
        direction.applyQuaternion(camera.quaternion);
        direction.y = 0;
        direction.normalize();
        testPosition.add(direction.multiplyScalar(moveSpeed));
        if (isPositionValid(testPosition)) {
          camera.translateX(-moveSpeed);
        }
      }
      if (moveState.right) {
        const testPosition = newPosition.clone();
        direction.set(1, 0, 0);
        direction.applyQuaternion(camera.quaternion);
        direction.y = 0;
        direction.normalize();
        testPosition.add(direction.multiplyScalar(moveSpeed));
        if (isPositionValid(testPosition)) {
          camera.translateX(moveSpeed);
        }
      }

      // Forcer la hauteur fixe
      camera.position.y = 1.7;
    };

    // Fonction pour vérifier si une position est valide
    const isPositionValid = (position: THREE.Vector3): boolean => {
      const ROOM_RADIUS = 9.5;

      // Vérifier les limites de la salle circulaire
      const distanceFromCenter = Math.sqrt(
        position.x * position.x + position.z * position.z
      );
      if (distanceFromCenter > ROOM_RADIUS) {
        return false;
      }

      // Vérifier les collisions avec les objets de la salle
      const playerBox = new THREE.Box3();
      const playerSize = new THREE.Vector3(0.5, 1.7, 0.5);
      playerBox.setFromCenterAndSize(position, playerSize);

      // Parcourir tous les objets de la scène pour vérifier les collisions
      let hasCollision = false;
      sceneRef.current?.traverse((object) => {
        if (object instanceof THREE.Mesh && object.userData.collidable) {
          const objectBox = new THREE.Box3().setFromObject(object);
          if (playerBox.intersectsBox(objectBox)) {
            hasCollision = true;
          }
        }
      });

      return !hasCollision;
    };

    // Animation
    const animate = () => {
      requestAnimationFrame(animate);
      updatePlayerPosition();
      renderer.render(scene, camera);
    };

    // Event listeners
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('click', handleClick);
    document.addEventListener('pointerlockchange', () => {
      if (document.pointerLockElement) {
        controlsRef.current?.connect();
      } else {
        controlsRef.current?.disconnect();
      }
    });

    animate();

    // Gestion du redimensionnement
    const handleResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('click', handleClick);
      document.removeEventListener('pointerlockchange', () => {});
      window.removeEventListener('resize', handleResize);
      if (mountElement.contains(renderer.domElement)) {
        mountElement.removeChild(renderer.domElement);
      }
    };
  }, [onInteract, onUpdateGameState]);

  return <div ref={mountRef} style={{ cursor: 'pointer' }} />;
}; 