import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Register from './pages/Register';
import { EscapeGame } from './components/EscapeGame';
import { GameIntro } from './pages/GameIntro';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(!!localStorage.getItem('token'));

  useEffect(() => {
    const checkAuth = () => {
      setIsAuthenticated(!!localStorage.getItem('token'));
    };

    // Vérifier l'authentification au chargement
    checkAuth();

    // Écouter les changements de localStorage
    window.addEventListener('storage', checkAuth);
    
    return () => {
      window.removeEventListener('storage', checkAuth);
    };
  }, []);

  return (
    <Router>
      <div style={{
        minHeight: '100vh',
        backgroundColor: '#1a1a1a',
        color: 'white',
        padding: 0
      }}>
        <Routes>
          <Route path="/login" element={isAuthenticated ? <Navigate to="/intro" replace /> : <Login setIsAuthenticated={setIsAuthenticated} />} />
          <Route path="/register" element={<Register />} />
          <Route 
            path="/intro" 
            element={
              isAuthenticated ? <GameIntro /> : <Navigate to="/login" replace />
            } 
          />
          <Route 
            path="/game" 
            element={
              isAuthenticated ? <EscapeGame /> : <Navigate to="/login" replace />
            } 
          />
          <Route path="*" element={<Navigate to="/login" replace />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
