import React, { useState, useEffect } from 'react';
import { SecretChamber3D } from './3d/SecretChamber3D/SecretChamber3D';
import { Bibliotheque3D } from './3d/Bibliotheque3D/Bibliotheque3D';
import { Inventory } from './ui/Inventory/Inventory';
import { GameState } from '../types/gameState';
import { InventoryItem } from '../types/gameTypes';

export const EscapeGame: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    score: 1000,
    elapsedTime: 0,
    hasFoundAncientBook: false,
    hasDecodedSymbols: false,
    hasAncientKey: false,
    hasExaminedMicroscope: false,
    hasCompletedChemicalMix: false,
    hasCrystalKey: false,
    hasPlacedArtifact: false,
    hasCompletedRitual: false,
    currentHint: undefined,
    gameCompleted: false,
    currentRoom: 'library',
    inventory: []
  });

  const [inventory, setInventory] = useState<InventoryItem[]>([]);

  useEffect(() => {
    // Charger l'état du jeu depuis le serveur
    const loadGameState = async () => {
      const token = localStorage.getItem('token');
      if (!token) return;

      try {
        const response = await fetch('http://localhost:3001/api/game/current', {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        });

        if (response.ok) {
          const data = await response.json();
          if (data.data) {
            setGameState(data.data);
            setInventory(data.data.inventory || []);
          }
        }
      } catch (error) {
        console.error('Erreur lors du chargement de l\'état du jeu:', error);
      }
    };

    loadGameState();
  }, []);

  const handleInteract = async (objectId: string, objectType: string) => {
    console.log(`Interaction avec l'objet ${objectId} de type ${objectType}`);
    // Logique d'interaction à implémenter
  };

  const handleUseItem = (item: InventoryItem) => {
    console.log(`Utilisation de l'objet ${item.name}`);
    // Logique d'utilisation d'objets à implémenter
  };

  const updateGameState = (newState: Partial<GameState>) => {
    setGameState(prevState => ({
      ...prevState,
      ...newState
    }));
  };

  return (
    <div className="escape-game" style={{ width: '100vw', height: '100vh', position: 'relative' }}>
      {gameState.currentRoom === 'library' ? (
        <Bibliotheque3D
          onInteract={handleInteract}
          roomType="library"
        />
      ) : (
        <SecretChamber3D
          onInteract={handleInteract}
          onUpdateGameState={updateGameState}
        />
      )}
      <div style={{ position: 'absolute', bottom: 20, right: 20, width: '300px' }}>
        <Inventory items={inventory} onUseItem={handleUseItem} />
      </div>
    </div>
  );
}; 